{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Public IP assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "Instances launched by this configuration are explicitly assigned public IP addresses, increasing their exposure to internet-originated traffic."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service v1 is permitted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not require IMDSv2, allowing instances to use the less secure sessionless IMDSv1 protocol."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Root EBS volume encryption is not enforced",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly encrypt its root EBS volume, which may leave instance data unencrypted at rest."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n\n  user_data = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n}\n",
  "fix_summary": "Disabled automatic public IP assignment, required IMDSv2, and enabled encryption for the root EBS volume."
}
